// Function to format number with commas
char* format_with_commas(double num) {
    char* str = malloc(100);
    int idx = 0;
    int has_decimal = 0;
    int decimal_pos = -1;

    // Check if it's negative
    int is_negative = 0;
    if (num < 0) {
        is_negative = 1;
        num = -num;
    }

    // Handle decimal point
    if (num >= 1000000000.0) {
        idx = 8;
    } else if (num >= 100000000.0) {
        idx = 7;
    } else if (num >= 10000000.0) {
        idx = 6;
    } else if (num >= 1000000.0) {
        idx = 5;
    } else if (num >= 100000.0) {
        idx = 4;
    } else if (num >= 10000.0) {
        idx = 3;
    } else if (num >= 1000.0) {
        idx = 2;
    } else if (num >= 100.0) {
        idx = 1;
    } else if (num >= 10.0) {
        idx = 0;
    }

    if (num >= 10.0) {
        idx = 0;
    }

    // Build integer part
    while (num >= 10 && idx > 0) {
        int digit = (int)(num % 10);
        str[idx] = '0' + digit;
        num /= 10;
        idx--;
    }
    if (num < 10) {
        str[idx] = '0' + (int)num;
        idx--;
    }
    str[idx] = 0;

    // Add commas
    for (int i = idx; i >= 0; i -= 3) {
        if (i > 0) {
            str[--i] = ',';
        }
    }

    // Add decimal part if needed
    if (num < 10 && num >= 1.0) {
        idx = -1;
        str[idx] = '.';
        idx--;
    }

    return str;
}

