import json
import sys

def deep_merge(a, b):
    if isinstance(a, dict) and isinstance(b, dict):
        result = {}
        all_keys = set(a.keys()) | set(b.keys())
        for key in all_keys:
            if key in a and key in b:
                result[key] = deep_merge(a[key], b[key])
            elif key in a:
                result[key] = a[key]
            else:
                result[key] = b[key]
        return result
    elif isinstance(a, list) and isinstance(b, list):
        return remove_duplicates(a + b)
    else:
        return b

def remove_duplicates(lst):
    result = []
    for item in lst:
        if item not in result:
            result.append(item)
    return result

