func sortRecursive(_ obj: Any) -> Any {
    if let dict = obj as? [AnyHashable: Any] {
        let keys = dict.keys.sorted { (key1: AnyHashable, key2: AnyHashable) in
            let s1 = key1 as? String ?? ""
            let s2 = key2 as? String ?? ""
            return s1 < s2
        }
        return Dictionary(keys: keys, values: keys.map { key in
            if let v = dict[key] {
                return sortRecursive(v)
            }
            return nil
        }.compactMap { $0 })
    }
    if let arr = obj as? [Any] {
        return arr.map { sortRecursive($0) }
    }
    return obj
}

