import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        String filePath = "/tmp/…/app.log";

        Map<String, Integer> levelCounts = new TreeMap<>(); // Sorted alphabetically
        Map<String, Integer> errorComponentCounts = new HashMap<>();
        Set<String> errorMessages = new TreeSet<>(); // Sorted alphabetically
        Map<String, Integer> hourCounts = new HashMap<>();

        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                // Regex to match format: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
                // Example: [2023-10-05 14:30:45] INFO (Database) - Connection established
                String[] parts = line.trim().split("\\]");
                if (parts.length < 2) continue;

                String timestamp = parts[0];
                String rest = parts[1];

                // Parse timestamp
                String[] timeParts = timestamp.split(" ");
                if (timeParts.length >= 2) {
                    String timeStr = timeParts[1];
                    String[] timeFields = timeStr.split(":");
                    if (timeFields.length >= 1) {
                        String hour = timeFields[0];
                        hourCounts.put(hour, hourCounts.getOrDefault(hour, 0) + 1);
                    }
                }

                // Parse rest: LEVEL (component) - message
                // Split by space to find LEVEL
                // Format: LEVEL (component) - message
                // First word is LEVEL
                String[] levelParts = rest.split("\\s+");
                if (levelParts.length < 1) continue;

                String level = levelParts[0];
                levelCounts.put(level, levelCounts.getOrDefault(level, 0) + 1);

                if (level.equals("ERROR")) {
                    // Find component
                    // Rest of line after LEVEL
                    // Format: (component) - message
                    // Find first '('
                    int openParen = rest.indexOf('(');
                    int closeParen = rest.indexOf(')');
                    if (openParen != -1 && closeParen != -1 && closeParen > openParen) {
                        String comp = rest.substring(openParen + 1, closeParen);
                        errorComponentCounts.put(comp, errorComponentCounts.getOrDefault(comp, 0) + 1);

                        // Find message
                        int dashIndex = rest.indexOf(" - ");
                        if (dashIndex != -1) {
                            String msg = rest.substring(dashIndex + 3);
                            errorMessages.add(msg);
                        }
                    }
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
            return;
        }

        // Output
        System.out.println("=== Log Analysis ===");
        System.out.println();

        System.out.println("Entries by Level:");
        for (Map.Entry<String, Integer> entry : levelCounts.entrySet()) {
            System.out.println("  " + entry.getKey() + ": " + entry.getValue());
        }

        System.out.println();

        // Component with Most Errors
        int maxErrors = -1;
        String maxComponent = "N/A";
        for (Map.Entry<String, Integer> entry : errorComponentCounts.entrySet()) {
            if (entry.getValue() > maxErrors) {
                maxErrors = entry.getValue();
                maxComponent = entry.getKey();
            }
        }
        System.out.println("Component with Most Errors: " + maxComponent + " (" + maxErrors + " errors)");

        System.out.println();

        // Unique Error Messages
        System.out.println("Unique Error Messages:");
        for (String msg : errorMessages) {
            System.out.println("  - " + msg);
        }

        System.out.println();

        // Busiest Hour
        int maxHourCount = -1;
        String busiestHour = "00:00"; // Default
        for (Map.Entry<String, Integer> entry : hourCounts.entrySet()) {
            if (entry.getValue() > maxHourCount) {
                maxHourCount = entry.getValue();
                busiestHour = entry.getKey() + ":00";
            }
        }
        System.out.println("Busiest Hour: " + busiestHour + " (" + maxHourCount + " entries)");
    }
}

func formatCommaInt(_ n: Int) -> String {
    let s = String(n)
    var groups = [String]()
    var i = s.count
    while i > 0 {
        let len = min(3, i)
        let start = max(0, i - len)
        groups.append(String(s[start..<i]))
        i = start
    }
    return groups.reversed().joined(separator: ",")
}

func formatAverage(_ value: Double) -> String {
    let s = String(format: "%.2f", value)
    let parts = s.split(separator: ".", maxSplits: 1)
    let intPart = String(parts[0])
    let decPart = String(parts[1])
    let formattedInt = formatCommaInt(Int(intPart))
    return "$" + formattedInt + "." + decPart
}

