import fs from 'fs';

const inputPath = '/tmp/…/graph.json';
const data = JSON.parse(fs.readFileSync(inputPath, 'utf-8'));

const nodes = new Set(data.nodes);
const adj: Map<string, Map<string, number>> = new Map();

for (const edge of data.edges) {
    const from = edge.from;
    const to = edge.to;
    const weight = edge.weight;

    if (!adj.has(from)) adj.set(from, new Map());
    if (!adj.has(to)) adj.set(to, new Map());
    adj.get(from)!.set(to, weight);
    adj.get(to)!.set(from, weight);
}

const startNode = 'A';
const distances: Map<string, number> = new Map();
const visited = new Set<string>();

for (const node of nodes) {
    distances.set(node, Infinity);
}
if (distances.has(startNode)) {
    distances.set(startNode, 0);
}

while (distances.has(startNode) && distances.get(startNode) !== Infinity) {
    let minDist = Infinity;
    let currentNode = '';

    for (const [node, dist] of distances.entries()) {
        if (!visited.has(node) && dist < minDist) {
            minDist = dist;
            currentNode = node;
        }
    }

    if (currentNode === '') break;

    visited.add(currentNode);

    const neighbors = adj.get(currentNode) || new Map();
    for (const [neighbor, weight] of neighbors.entries()) {
        if (!visited.has(neighbor)) {
            const newDist = minDist + weight;
            if (newDist < distances.get(neighbor)!) {
                distances.set(neighbor, newDist);
            }
        }
    }
}

