void skip_ws(void) {
    while (pos < len && isspace((unsigned char)content[pos])) pos++;
}

Node *parse_value(void) {
    skip_ws();
    if (pos >= len) return NULL;
    char c = content[pos];
    if (c == '{') return parse_object();
    if (c == '[') return parse_array();
