    int total_keys = 0;
    for (int i = 0; i < a->obj_count; i++) total_keys++;
    for (int i = 0; i < b->obj_count; i++) total_keys++;

    // Sort keys for merge logic
    key_node *all_keys = malloc(total_keys * sizeof(key_node));
    int idx = 0;
    for (int i = 0; i < a->obj_count; i++) all_keys[idx++] = a->obj_keys[i];
    for (int i = 0; i < b->obj_count; i++) all_keys[idx++] = b->obj_keys[i];
    qsort(all_keys, total_keys, sizeof(key_node), compare_keys_node);

