        for (int j = 0; j < a->obj_count; j++) if (strcmp(all_keys[j].key, key) == 0) { found_a = 1; av = a->obj_keys[j].val; break; }
        for (int j = 0; j < b->obj_count; j++) if (strcmp(all_keys[j].key, key) == 0) { found_b = 1; bv = b->obj_keys[j].val; break; }

        Node *val = NULL;
        if (found_a && found_b) {
            if (av->type == OBJ && bv->type == OBJ) {
                val = merge_objects(av, bv);
            } else {
                val = bv;
            }
        } else if (found_a) {
            val = av;
        } else if (found_b) {
            val = bv;
        }

        if (res->obj_capacity == res->obj_count) {
            res->obj_capacity *= 2;
            res->obj_keys = realloc(res->obj_keys, res->obj_capacity * sizeof(key_node));
        }
        key_node *nk = malloc(sizeof(key_node));
        nk->key = key;
        nk->val = val;
        res->obj_keys[res->obj_count++] = *nk;
    }

    free(all_keys);
