    res->bool_val = false;
    if (res->arr_capacity == 0) res->arr_capacity = 16;
    res->arr_items = malloc(res->arr_capacity * sizeof(Node*));

    // Copy A items
    for (int i = 0; i < a->arr_count; i++) {
        if (res->arr_capacity == res->arr_count) {
            res->arr_capacity *= 2;
            res->arr_items = realloc(res->arr_items, res->arr_capacity * sizeof(Node*));
        }
        res->arr_items[res->arr_count++] = a->arr_items[i];
    }

    // Add B items if not duplicate
    for (int i = 0; i < b->arr_count; i++) {
        Node *bv = b->arr_items[i];
        int exists = 0;
        for (int j = 0; j < res->arr_count; j++) {
            if (nodes_equal(res->arr_items[j], bv)) {
