Node *merge_nodes(Node *a, Node *b) {
    if (a->type == OBJ && b->type == OBJ) return merge_objects(a, b);
    if (a->type == ARR && b->type == ARR) return merge_arrays(a, b);
    if (b) return b;
    return a;
}

bool nodes_equal(Node *a, Node *b) {
    if (a->type != b->type) return false;
    if (a->type == OBJ) {
        if (a->obj_count != b->obj_count) return false;
        for (int i = 0; i < a->obj_count; i++) {
            if (strcmp(a->obj_keys[i].key, b->obj_keys[i].key) != 0) return false;
            if (!nodes_equal(a->obj_keys[i].val, b->obj_keys[i].val)) return false;
        }
        return true;
    }
    if (a->type == ARR) {
        if (a->arr_count != b->arr_count) return false;
        for (int i = 0; i < a->arr_count; i++) {
            if (!nodes_equal(a->arr_items[i], b->arr_items[i])) return false;
        }
        return true;
    }
    if (a->type == STR) return strcmp(a->str_val, b->str_val) == 0;
    if (a->type == NUM) return a->num_val == b->num_val;
    if (a->type == BOOL) return a->bool_val == b->bool_val;
    return true;
}

void free_node(Node *n) {
    if (!n) return;
    if (n->type == OBJ) {
        for (int i = 0; i < n->obj_count; i++) {
            if (n->obj_keys[i].val) free_node(n->obj_keys[i].val);
        }
        free(n->obj_keys);
