    if (n->type == ARR) {
        for (int i = 0; i < n->arr_count; i++) {
            if (n->arr_items[i]) free_node(n->arr_items[i]);
        }
        free(n->arr_items);
    }
    if (n->type == STR) free(n->str_val);
    free(n);
}

int compare_keys_node(const void *a, const void *b) {
