    res->obj_capacity = 0;
    res->arr_items = NULL;
    res->arr_count = 0;
    res->arr_capacity = 0;

    if (res->obj_capacity == 0) res->obj_capacity = 16;
    res->obj_keys = malloc(res->obj_capacity * sizeof(key_node));

    // Collect all keys
    int total_keys = 0;
    for (int i = 0; i < a->obj_count; i++) total_keys++;
    for (int i = 0; i < b->obj_count; i++) total_keys++;

    // Sort keys for merge logic
    key_node *all_keys = malloc(total_keys * sizeof(key_node));
    int idx = 0;
    for (int i = 0; i < a->obj_count; i++) all_keys[idx++] = a->obj_keys[i];
    for (int i = 0; i < b->obj_count; i++) all_keys[idx++] = b->obj_keys[i];
    qsort(all_keys, total_keys, sizeof(key_node), compare_keys_node);

    for (int i = 0; i < total_keys; i++) {
        char *key = all_keys[i].key;
        Node *av = NULL, *bv = NULL;
        int found_a = 0, found_b = 0;
        for (int j = 0; j < a->obj_count; j++) if (strcmp(all_keys[j].key, key) == 0) { found_a = 1; av = a->obj_keys[j].val; break; }
        for (int j = 0; j < b->obj_count; j++) if (strcmp(all_keys[j].key, key) == 0) { found_b = 1; bv = b->obj_keys[j].val; break; }

        Node *val = NULL;
        if (found_a && found_b) {
            if (av->type == OBJ && bv->type == OBJ) {
                val = merge_objects(av, bv);
            } else {
                val = bv; // B overrides A for scalars
            }
        } else if (found_a) {
            val = av;
        } else if (found_b) {
            val = bv;
        }

        if (res->obj_capacity == res->obj_count) {
            res->obj_capacity = res->obj_capacity == 0 ? 16 : res->obj_capacity * 2;
            res->obj_keys = realloc(res->obj_keys, res->obj_capacity * sizeof(key_node));
        }
        key_node *nk = malloc(sizeof(key_node));
        nk->key = key;
        nk->val = val;
        res->obj_keys[res->obj_count++] = *nk;
    }

    free(all_keys);
    return res;
}

Node *merge_arrays(Node *a, Node *b) {
    Node *res = malloc(sizeof(Node));
    res->type = ARR;
    res->str_val = NULL;
    res->num_val = 0.0;
    res->bool_val = false;
    res->obj_keys = NULL;
    res->obj_count = 0;
    res->obj_capacity = 0;
    res->arr_items = NULL;
    res->arr_count = 0;
    res->arr_capacity = 0;

    if (res->arr_capacity == 0) res->arr_capacity = 16;
    res->arr_items = malloc(res->arr_capacity * sizeof(Node*));

    // Copy A items
    for (int i = 0; i < a->arr_count; i++) {
        if (res->arr_capacity == res->arr_count) {
            res->arr_capacity = res->arr_capacity == 0 ? 16 : res->arr_capacity * 2;
            res->arr_items = realloc(res->arr_items, res->arr_capacity * sizeof(Node*));
        }
        res->arr_items[res->arr_count++] = a->arr_items[i];
    }

    // Add B items if not duplicate
    for (int i = 0; i < b->arr_count; i++) {
        Node *bv = b->arr_items[i];
        int exists = 0;
        for (int j = 0; j < res->arr_count; j++) {
            if (nodes_equal(res->arr_items[j], bv)) {
                exists = 1;
                break;
            }
        }
        if (!exists) {
            if (res->arr_capacity == res->arr_count) {
                res->arr_capacity = res->arr_capacity == 0 ? 16 : res->arr_capacity * 2;
                res->arr_items = realloc(res->arr_items, res->arr_capacity * sizeof(Node*));
            }
            res->arr_items[res->arr_count++] = bv;
        }
    }

    return res;
}

Node *merge_nodes(Node *a, Node *b) {
    if (a->type == OBJ && b->type == OBJ) return merge_objects(a, b);
    if (a->type == ARR && b->type == ARR) return merge_arrays(a, b);
    if (b) return b;
    return a;
}

bool nodes_equal(Node *a, Node *b) {
    if (!a || !b) return false;
    if (a->type != b->type) return false;
    if (a->type == OBJ) {
        if (a->obj_count != b->obj_count) return false;
        for (int i = 0; i < a->obj_count; i++) {
            if (strcmp(a->obj_keys[i].key, b->obj_keys[i].key) != 0) return false;
            if (!nodes_equal(a->obj_keys[i].val, b->obj_keys[i].val)) return false;
        }
        return true;
    }
    if (a->type == ARR) {
        if (a->arr_count != b->arr_count) return false;
        for (int i = 0; i < a->arr_count; i++) {
            if (!nodes_equal(a->arr_items[i], b->arr_items[i])) return false;
        }
        return true;
    }
    if (a->type == STR) return strcmp(a->str_val, b->str_val) == 0;
    if (a->type == NUM) return a->num_val == b->num_val;
    if (a->type == BOOL) return a->bool_val == b->bool_val;
    return true;
}

void free_node(Node *n) {
    if (!n) return;
    if (n->type == OBJ) {
        for (int i = 0; i < n->obj_count; i++) {
            if (n->obj_keys[i].val) free_node(n->obj_keys[i].val);
        }
        free(n->obj_keys);
    }
    if (n->type == ARR) {
        for (int i = 0; i < n->arr_count; i++) {
            if (n->arr_items[i]) free_node(n->arr_items[i]);
        }
        free(n->arr_items);
    }
    if (n->type == STR) free(n->str_val);
    free(n);
}

int compare_keys_node(const void *a, const void *b) {
    return strcmp(((const key_node*)a)->key, ((const key_node*)b)->key);
}

void sort_keys(Node *n) {
    if (n->type == OBJ && n->obj_count > 0) {
        qsort(n->obj_keys, n->obj_count, sizeof(key_node), compare_keys_node);
    }
}

void print_value(Node *n, int indent) {
    if (!n) return;
    if (n->type == OBJ) {
        sort_keys(n);
        printf("%s{%s", indent > 0 ? "  " : "", "");
        if (n->obj_count > 0) printf("\n");
        for (int i = 0; i < n->obj_count; i++) {
            printf("%s  \"%s\": ", indent > 0 ? "  " : "", n->obj_keys[i].key);
            print_value(n->obj_keys[i].val, indent + 2);
            if (i < n->obj_count - 1) printf(", ");
        }
        if (n->obj_count > 0) printf("\n");
        printf("%s}", indent > 0 ? "  " : "");
    } else if (n->type == ARR) {
        printf("%s[", indent > 0 ? "  " : "");
        if (n->arr_count > 0) printf("\n");
        for (int i = 0; i < n->arr_count; i++) {
            print_value(n->arr_items[i], indent + 2);
            if (i < n->arr_count - 1) printf(", ");
        }
        if (n->arr_count > 0) printf("\n");
        printf("%s]", indent > 0 ? "  " : "");
    } else if (n->type == STR) {
        printf("%s\"", indent > 0 ? "  " : "");
        printf("%s", n->str_val);
        printf("%s\"", indent > 0 ? "  " : "");
    } else if (n->type == NUM) {
        printf("%s%g", indent > 0 ? "  " : "", n->num_val);
    } else if (n->type == BOOL) {
        printf("%s%s", indent > 0 ? "  " : "", n->bool_val ? "true" : "false");
    } else if (n->type == NULL_VAL) {
        printf("%snull", indent > 0 ? "  " : "");
    }
}

