            while (p < len && isspace((unsigned char)response[p])) p++;

            if (in_array && response[p] == ',') {
                p++;
            }
            continue;
        }

        if (in_array && in_object) {
            // Look for "name"
            if (!found_name) {
                size_t name_start = -1;
                size_t name_end = -1;

                char *ptr = strstr(response + p, "\"name\":");
                if (ptr) {
                    ptr += strlen("\"name\":");
                    if (ptr < response + len && *ptr == '"') {
                        ptr++; // Skip opening quote
                        name_start = ptr - response;
                        while (ptr < response + len && !isspace((unsigned char)*ptr) && *ptr != '"' && *ptr != ',' && *ptr != '}') {
                            ptr++;
                        }
                        name_end = ptr - response;
                        if (name_end < len && response[name_end] == '"') {
                            name_end++;
                        }
                    }
                }

                if (name_start != -1 && name_end != -1) {
                    size_t name_len = name_end - name_start;
                    if (name_len < MAX_PRODUCT_NAME) {
                        strncpy((*products)[*count].name, response + name_start, name_len);
                        (*products)[*count].name[name_len] = '\0';
                        found_name = 1;
                    }
                }
            }

            // Look for "price"
            if (!found_price) {
                char *ptr = strstr(response + p, "\"price\":");
                if (ptr) {
                    ptr += strlen("\"price\":");
                    while (ptr < response + len && isspace((unsigned char)*ptr)) {
                        ptr++;
                    }
                    if (ptr < response + len && *ptr == ':') {
                        ptr++;
                    }
                    while (ptr < response + len && isspace((unsigned char)*ptr)) {
                        ptr++;
                    }

                    // Parse double
                    char *endptr;
                    double val = strtod(ptr, &endptr);
                    if (endptr != ptr) {
                        (*products)[*count].price = val;
                        found_price = 1;
                    }
                }
            }

            if (found_name && found_price) {
                // Check filter
                if ((*products)[*count].price > 50.00) {
                    (*total) += (*products)[*count].price;
                    (*count)++;
                }

                // Reset for next object
                found_name = 0;
                found_price = 0;

                // Break if end of array
                if (in_array && response[p] == ']' || (in_array && response[p] == ',')) {
                    break;
                }
                p++; // Skip comma or brace
            }
        }

        if (p < len) p++;
    }

    return 0;
}

int http_get(const char *url, const char *response_buffer, size_t *response_len) {
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = IPPROTO_TCP;

    const char *host = "127.0.0.1";
    const char *port = "18923";
    char port_str[10];
    snprintf(port_str, sizeof(port_str), "%s", port);

    if (getaddrinfo(host, port_str, &hints, &res) != 0) {
        return -1;
    }

    int sock = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (sock < 0) {
        freeaddrinfo(res);
        return -1;
    }

    if (connect(sock, res->ai_addr, res->ai_addrlen) < 0) {
        close(sock);
        freeaddrinfo(res);
        return -1;
    }

    char *request = "GET /api/products HTTP/1.1\r\nHost: 127.0.0.1:18923\r\n\r\n";
    size_t req_len = strlen(request);
    if (send(sock, request, req_len, 0) < 0) {
        close(sock);
        freeaddrinfo(res);
        return -1;
    }

    *response_len = 0;
    while (*response_len < MAX_RESPONSE_SIZE) {
        char buf[4096];
        size_t n = recv(sock, buf, sizeof(buf), 0);
        if (n <= 0) break;
        for (size_t i = 0; i < n; i++) {
            response_buffer[*response_len + i] = buf[i];
        }
        *response_len += n;
    }

    close(sock);
    freeaddrinfo(res);
    return 0;
}

