fn get_file_stats(path: &Path) -> (u64, u64) {
    let file = File::open(path).expect("Failed to open file");
    let reader = BufReader::new(file);

    let mut lines = 0;
    let mut chars = 0;

    for line in reader.lines() {
        let line = match line {
            Ok(l) => l,
            Err(_) => break,
        };
        lines += 1;
        chars += line.len();
    }

    (lines, chars)
