    static class FileStats {
        String relativePath;
        int lines;
        int chars;

        FileStats(String relativePath, int lines, int chars) {
            this.relativePath = relativePath;
            this.lines = lines;
            this.chars = chars;
        }
    }

    static void walkDirectory(Path path, Map<String, List<FileStats>> filesByExtension, int totalFiles, int totalLines, int totalChars) {
        try {
            // Check if it's a directory first
            if (Files.isDirectory(path)) {
                // List files in this directory
                try (Stream<Path> entries = Files.list(path)) {
                    entries.forEach(entry -> {
                        if (Files.isRegularFile(entry) && !Files.isSymbolicLink(entry)) {
                            // Get relative path
                            String relativePath = entry.toRealPath().relativize(root).toString();

                            // Get extension
                            String ext = getFileExtension(entry);

                            // Calculate stats
                            FileStats stats = getFileStats(entry);

                            // Add to map
                            filesByExtension.computeIfAbsent(ext, k -> new ArrayList<>()).add(new FileStats(relativePath, stats.lines, stats.chars));

                            totalFiles++;
                            totalLines += stats.lines;
                            totalChars += stats.chars;
                        }
                    });
                }
            }
        } catch (Exception e) {
            // Continue even if there are errors
        }
    }

    static String getFileExtension(Path path) {
        String filename = path.getFileName().toString();
        int lastDot = filename.lastIndexOf('.');
        if (lastDot > 0 && lastDot < filename.length() - 1) {
            return "." + filename.substring(lastDot);
        }
        return "";
    }

    static FileStats getFileStats(Path path) throws IOException {
        try (RandomAccessFile raf = new RandomAccessFile(path.toFile(), "r")) {
            long fileSize = raf.length();
            long totalChars = 0;
            int lineCount = 0;

            // Read file and count lines and chars
            byte[] buffer = new byte[(int) Math.min(fileSize, 1024 * 1024)]; // 1MB buffer
            raf.read(buffer);

            totalChars = buffer.length;

            // Count lines
            String content = new String(buffer, StandardCharsets.UTF_8);
            lineCount = countLines(content);

            return new FileStats(path.getFileName().toString(), lineCount, (int)totalChars);
        }
    }

    static int countLines(String content) {
        if (content == null || content.isEmpty()) {
            return 0;
        }
        int count = 0;
        for (int i = 0; i < content.length(); i++) {
            if (content.charAt(i) == '\n') {
                count++;
            }
        }
        return count;
    }
}

