var filesByExt: [String: [String]] = [:]

func walkDirectory(_ path: String) {
    guard FileManager.default.fileExists(atPath: path) else { return }

    let contents = try! FileManager.default.contentsOfDirectory(
        at: path,
        includingPropertiesForKeys: nil
    )

    for entry in contents {
        let fullPath = path + "/" + entry
        let attrs = try! FileManager.default.attributesOfItem(atPath: fullPath)
        let fileType = attrs[.fileType] as? UInt

        if fileType == .file {
            let (lines, chars) = countFileMetrics(fullPath)
            let ext = entry.components(separatedBy: ".").last ?? ""
            let extKey = "." + ext

            filesByExt[extKey, default: []].append((fullPath, lines, chars))
        } else if fileType == .directory {
            walkDirectory(fullPath)
        }
    }
}

func countFileMetrics(_ path: String) -> (lines: Int, chars: Int) {
    do {
        let content = try String(contentsOfFile: path, encoding: .utf8)
        let lines = content.split(separator: "\n").count
        let chars = content.utf8.count
        return (lines, chars)
    } catch {
        return (0, 0)
    }
}

