        for (String node : nodes) {
            adj.put(node, new ArrayList<>());
        }

        // Add nodes from edges if not in nodes list (to ensure completeness)
        for (Edge e : edges) {
            adj.computeIfAbsent(e.to, k -> new ArrayList<>());
            adj.computeIfAbsent(e.from, k -> new ArrayList<>());
        }

