    private static List<String> parseNodes(String content) {
        List<String> nodes = new ArrayList<>();
        int start = content.indexOf("nodes");
        int end = content.indexOf("]");
        if (start == -1 || end == -1) return nodes;

        String nodesStr = content.substring(start, end);
        // Remove "nodes": and [
        nodesStr = nodesStr.replaceFirst("\"nodes\":", "").replaceFirst("\\[", "").replaceFirst("\\]", "");

        String[] parts = nodesStr.split(",");
        for (String p : parts) {
            p = p.trim();
            if (p.startsWith("\"") && p.endsWith("\"")) {
                nodes.add(p.substring(1, p.length() - 1));
            }
        }
        return nodes;
    }

    private static List<Edge> parseEdges(String content) {
        List<Edge> edges = new ArrayList<>();
        int start = content.indexOf("edges");
        int end = content.indexOf("]");
        if (start == -1 || end == -1) return edges;

        String edgesStr = content.substring(start, end);
        // Remove "edges": and [
        edgesStr = edgesStr.replaceFirst("\"edges\":", "").replaceFirst("\\[", "").replaceFirst("\\]", "");

        // Split by }, {
        String[] edgeObjects = edgesStr.split("},\\s*\\{");
        // Handle last element which might not have closing brace if split logic varies
        // Actually split("},") is safer if we clean up
        String[] rawObjects = edgesStr.split("},");
        for (int i = 0; i < rawObjects.length; i++) {
            String obj = rawObjects[i];
            // Remove leading {
            if (obj.startsWith("{")) obj = obj.substring(1);
            // Remove trailing }
            if (obj.endsWith("}")) obj = obj.substring(0, obj.length() - 1);

            String from = extractString(obj, "from");
            String to = extractString(obj, "to");
            int weight = extractInt(obj, "weight");

            if (from != null && to != null) {
                edges.add(new Edge(to, weight));
            }
        }
        return edges;
    }

    private static String extractString(String obj, String key) {
        int start = obj.indexOf("\"" + key + "\"");
        if (start == -1) return null;
        start += key.length() + 2; // skip key and :
        if (start >= obj.length()) return null;
        if (obj.charAt(start) != '"') return null; // Should be string
        int end = obj.indexOf('"', start + 1);
        if (end == -1) return null;
        return obj.substring(start + 1, end);
    }

    private static int extractInt(String obj, String key) {
        int start = obj.indexOf("\"" + key + "\"");
        if (start == -1) return 0;
        start += key.length() + 2;
        if (start >= obj.length()) return 0;
        if (obj.charAt(start) != ':') return 0;
        start++;
        if (start >= obj.length()) return 0;
        // Skip whitespace
        while (start < obj.length() && Character.isWhitespace(obj.charAt(start))) start++;
        if (start >= obj.length()) return 0;

        int num = 0;
        while (start < obj.length() && Character.isDigit(obj.charAt(start))) {
            num = num * 10 + (obj.charAt(start) - '0');
            start++;
        }
        return num;
    }
