import fs from 'fs';
import path from 'path';

const PROJECT_TREE = '/tmp/…/project_tree';

const walk = (dir: string, base: string): void => {
  try {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);
      const stats = fs.lstatSync(fullPath);
      if (stats.isSymbolicLink()) {
        continue;
      }
      if (stats.isDirectory()) {
        walk(fullPath, base);
      } else if (stats.isFile()) {
        const relativePath = path.posix.relative(base, fullPath);
        const ext = path.posix.extname(fullPath);
        const content = fs.readFileSync(fullPath, 'utf-8');
        const lines = content.split('\n').length;
        if (content.endsWith('\n')) {
          lines--;
        }
        const chars = content.length;
        console.log(`    ${relativePath}: ${lines} lines, ${chars} chars`);
      }
    }
  } catch (e) {
    console.error(`Error processing ${dir}:`, e);
  }
};

const processFile = (filePath: string): { ext: string, lines: number, chars: number } => {
  const stats = fs.lstatSync(filePath);
  if (stats.isSymbolicLink()) {
    return { ext: '', lines: 0, chars: 0 };
  }
  if (!stats.isFile()) {
    return { ext: '', lines: 0, chars: 0 };
  }
  const ext = path.posix.extname(filePath);
  const content = fs.readFileSync(filePath, 'utf-8');
  const lines = content.split('\n').length;
  if (content.endsWith('\n')) {
    lines--;
  }
  const chars = content.length;
  return { ext, lines, chars };
};

const analyzeDir = (dir: string): Record<string, { count: number, lines: number, chars: number, files: string[] }> => {
  const groups: Record<string, { count: number, lines: number, chars: number, files: string[] }> = {};
  const walkRecursive = (currentDir: string): void => {
    try {
      const entries = fs.readdirSync(currentDir, { withFileTypes: true });
      for (const entry of entries) {
        const fullPath = path.join(currentDir, entry.name);
        const stats = fs.lstatSync(fullPath);
        if (stats.isSymbolicLink()) {
          continue;
        }
        if (stats.isDirectory()) {
          walkRecursive(fullPath);
        } else if (stats.isFile()) {
          const relativePath = path.posix.relative(dir, fullPath);
          const { ext, lines, chars } = processFile(fullPath);
          if (!groups[ext]) {
            groups[ext] = { count: 0, lines: 0, chars: 0, files: [] };
          }
          groups[ext].count++;
          groups[ext].lines += lines;
          groups[ext].chars += chars;
          groups[ext].files.push(relativePath);
        }
      }
    } catch (e) {
      console.error(`Error processing ${currentDir}:`, e);
    }
  };
  walkRecursive(dir);
  return groups;
};

