static char *json_ptr;
static char *json_end;

static int peek_char() {
    if (json_ptr >= json_end) return -1;
    return (unsigned char)*json_ptr;
}

static int get_char() {
    if (json_ptr >= json_end) return -1;
    int c = (unsigned char)*json_ptr;
    json_ptr++;
    return c;
}

static void skip_ws() {
    while (json_ptr < json_end) {
        int c = peek_char();
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r') {
            get_char();
        } else {
            return;
        }
    }
}

