            if (!g->visited[j] && g->dist[j] < min_dist) {
                min_dist = g->dist[j];
                u = j;
            }
        }
        if (u == -1 || min_dist == INF) break;
        g->visited[u] = true;
        EdgeNode *e = g->adj[u];
        while (e) {
            int v = e->to;
            if (!g->visited[v] && e->weight + g->dist[u] < g->dist[v]) {
                g->dist[v] = (long long)e->weight + g->dist[u];
            }
            e = e->next;
        }
    }
}

static void free_graph(Graph *g) {
    if (g) {
        for (int i = 0; i < g->node_count; i++) {
            free(g->nodes[i].name);
        }
        free(g->nodes);
        for (int i = 0; i < MAX_NODES; i++) {
            if (g->adj[i]) free(g->adj[i]);
        }
        free(g->adj);
        free(g->dist);
        free(g->visited);
        free(g);
    }
}

